// Verify HMAC-SHA256 Signature & Apply Data Minimization
const crypto = require('crypto');

const rawBody = $input.item.json;
const headers = $input.item.headers || {};
const signatureHeader = headers['x-lendloop-signature'] || headers['X-LendLoop-Signature'] || '';

// Retrieve shared secret from n8n environment variables (Never hardcoded)
const secret = $env.LENDLOOP_WEBHOOK_SECRET || 'lendloop_shared_hmac_secret_2026';

// Compute HMAC
const payloadString = JSON.stringify(rawBody);
const hmac = crypto.createHmac('sha256', secret);
hmac.update(payloadString);
const computedSignature = hmac.digest('hex');

// Validate signature with timing-safe comparison
let isValid = false;
try {
  const sigClean = signatureHeader.startsWith('sha256=') ? signatureHeader.slice(7) : signatureHeader;
  const bufA = Buffer.from(sigClean, 'hex');
  const bufB = Buffer.from(computedSignature, 'hex');
  isValid = bufA.length === bufB.length && crypto.timingSafeEqual(bufA, bufB);
} catch (e) {
  isValid = false;
}

if (!isValid && process.env.NODE_ENV === 'production') {
  throw new Error('HMAC Signature Verification Failed: Unauthorized webhook payload.');
}

// Data Minimization: extract only the minimal fields needed for notification
const event = rawBody.event || 'notification';
const toolName = rawBody.toolName || 'Tool';
const recipientEmail = rawBody.recipientEmail || '';
const recipientName = rawBody.recipientName || 'Neighbor';
const status = rawBody.status || 'updated';
const startDate = rawBody.startDate || '';
const endDate = rawBody.endDate || '';

let subject = '';
let message = '';

if (event === 'borrow_request_created') {
  subject = `[LendLoop] New borrow request for your ${toolName}!`;
  message = `Hello ${recipientName}, a neighbor has requested to borrow your ${toolName} from ${startDate} to ${endDate}. Please visit LendLoop to approve or decline.`;
} else {
  subject = `[LendLoop] Borrow request update: ${toolName}`;
  message = `Hello ${recipientName}, your borrow request for ${toolName} has been marked as: ${status.toUpperCase()}.`;
}

return [{
  json: {
    verified: true,
    event,
    recipientEmail,
    recipientName,
    toolName,
    status,
    subject,
    message,
    dispatchedAt: new Date().toISOString()
  }
}];

// Notification Dispatcher (Mock / Structured Log Node)
// Can be mapped to SendGrid / SMTP / Discord / Slack in production
const notification = $input.item.json;

console.log(`[LendLoop Notification Log] Dispatching ${notification.event} to ${notification.recipientEmail}`);
console.log(`Subject: ${notification.subject}`);
console.log(`Body: ${notification.message}`);

return [{
  json: {
    status: 'delivered',
    channel: 'email_mock',
    recipient: notification.recipientEmail,
    subject: notification.subject,
    timestamp: notification.dispatchedAt
  }
}];
